-- 第三阶段：在已完成 0003 的 CHANNEL_DB 中执行一次。
ALTER TABLE students ADD COLUMN billing_mode TEXT NOT NULL DEFAULT 'package';
ALTER TABLE packages ADD COLUMN unit_price REAL;
ALTER TABLE packages ADD COLUMN amount REAL;
ALTER TABLE packages ADD COLUMN stage_id TEXT;
ALTER TABLE packages ADD COLUMN purchase_date TEXT NOT NULL DEFAULT '';
ALTER TABLE packages ADD COLUMN scope_kind TEXT NOT NULL DEFAULT 'type';
ALTER TABLE packages ADD COLUMN category_id TEXT;
ALTER TABLE lessons ADD COLUMN teacher_paid INTEGER NOT NULL DEFAULT 0;
CREATE TABLE student_stages(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT NOT NULL,name TEXT NOT NULL,date_from TEXT,date_to TEXT,goal TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE package_transactions(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,package_id TEXT NOT NULL,student_id TEXT NOT NULL,delta REAL NOT NULL,type TEXT NOT NULL,date TEXT NOT NULL,participant_id TEXT,reference_id TEXT,note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,package_id) REFERENCES packages(tenant_id,id),FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id),FOREIGN KEY(tenant_id,participant_id) REFERENCES lesson_participants(tenant_id,id));
CREATE TABLE student_payments(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT NOT NULL,package_id TEXT,amount REAL NOT NULL,paid_at TEXT NOT NULL,method TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id),FOREIGN KEY(tenant_id,package_id) REFERENCES packages(tenant_id,id));
CREATE TABLE makeup_links(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,original_participant_id TEXT NOT NULL,target_participant_id TEXT NOT NULL,target_lesson_id TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,original_participant_id) REFERENCES lesson_participants(tenant_id,id),FOREIGN KEY(tenant_id,target_participant_id) REFERENCES lesson_participants(tenant_id,id),FOREIGN KEY(tenant_id,target_lesson_id) REFERENCES lessons(tenant_id,id));
CREATE TABLE settlements(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,month TEXT NOT NULL,locked INTEGER NOT NULL DEFAULT 0,summary TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE TABLE credit_operations(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,actor_id TEXT NOT NULL,request_hash TEXT NOT NULL,response_json TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE INDEX transaction_student ON package_transactions(tenant_id,student_id,package_id);
CREATE INDEX transaction_participant ON package_transactions(tenant_id,participant_id);
CREATE INDEX payments_student ON student_payments(tenant_id,student_id,paid_at);
CREATE UNIQUE INDEX makeup_target ON makeup_links(tenant_id,target_participant_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX settlement_month ON settlements(tenant_id,month);
CREATE TRIGGER ledger_no_update BEFORE UPDATE ON package_transactions BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER ledger_no_delete BEFORE DELETE ON package_transactions BEGIN SELECT RAISE(ABORT,'append only'); END;
UPDATE packages SET purchase_date=COALESCE(valid_from,date(created_at/1000,'unixepoch','+8 hours'));
INSERT INTO package_transactions(tenant_id,id,package_id,student_id,delta,type,date,created_at,created_by,updated_at,updated_by) SELECT tenant_id,'txn_'||lower(hex(randomblob(12))),id,student_id,units_total,'opening',purchase_date,created_at,'system_migration',updated_at,'system_migration' FROM packages WHERE units_total<>0;
CREATE TRIGGER package_stage_reference BEFORE INSERT ON packages WHEN NEW.stage_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM student_stages WHERE tenant_id=NEW.tenant_id AND id=NEW.stage_id AND student_id=NEW.student_id AND deleted_at IS NULL) THEN RAISE(ABORT,'invalid_stage_reference') END; END;
CREATE TRIGGER package_stage_update_reference BEFORE UPDATE OF stage_id,student_id ON packages WHEN NEW.stage_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM student_stages WHERE tenant_id=NEW.tenant_id AND id=NEW.stage_id AND student_id=NEW.student_id AND deleted_at IS NULL) THEN RAISE(ABORT,'invalid_stage_reference') END; END;
